exportData = function() { if (exportInProgress) return; exportInProgress = true; const payload = { format: 'cpos-pack-content-v1', packs: data.packs.map(packContent) }; const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'cpos-pack-content.json'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => { URL.revokeObjectURL(a.href); exportInProgress = false; }, 800); toast('Pack content exported.'); };
document.getElementById('import-file').addEventListener('change', async e => { e.stopImmediatePropagation(); const file = e.target.files[0]; if (!file) return; try { const imported = JSON.parse(await file.text()); if (!Array.isArray(imported.packs)) throw Error(); const incoming = imported.packs.map(packContent); const merged = new Map(data.packs.map(pack => [pack.id, pack])); incoming.forEach(pack => { const existing = merged.get(pack.id); merged.set(pack.id, existing ? { ...existing, ...pack, openedCount: existing.openedCount || 0, favorite: existing.favorite || false } : pack); }); data.packs = [...merged.values()]; data.obtained = data.obtained || {}; save(); render(); toast(`${incoming.length} pack${incoming.length === 1 ? '' : 's'} imported.`); } catch { toast('That file is not valid CPOS pack content.'); } e.target.value = ''; }, true);
