// Revised editor flow: a slot stores an array of possible rarity ids.
function editor() { const p = view.editor; const rarityOptions = p.rarities.map(r => `<option value="${r.id}">${escapeHtml(r.name)}</option>`).join(''); return `<section class="editor-head"><div><div class="eyebrow">Pack workshop</div><h1>${p.id ? 'Edit pack' : 'Create a pack'}</h1></div><div class="editor-actions"><button class="button button-quiet" data-action="home">Cancel</button><button class="button button-primary" data-action="save-pack">Save pack</button></div></section><div class="editor-grid"><div class="panel"><div class="cover-preview"><div class="pack-cover">${cover(p)}</div></div><div class="field"><label>Pack cover image URL</label><input data-edit="cover" value="${escapeHtml(p.cover)}" placeholder="https://..." /></div><div class="field"><label>Pack name</label><input data-edit="name" value="${escapeHtml(p.name)}" placeholder="Name your pack" /></div><div class="field"><label>Description</label><textarea data-edit="description" placeholder="A short description">${escapeHtml(p.description)}</textarea></div></div><div class="editor-stack"><div class="panel"><h2>01 / Rarity system</h2><p>Define only the rarities this pack actually uses.</p><div class="row"><div class="field"><label>New rarity</label><input id="new-rarity" placeholder="e.g. Secret" /></div><button class="button button-quiet inline-add" data-action="add-rarity">Add rarity</button></div><div class="tag-list">${p.rarities.map(r => `<span class="tag">${escapeHtml(r.name)} <button data-action="remove-rarity" data-id="${r.id}">×</button></span>`).join('')}</div></div><div class="panel"><h2>02 / Pack structure</h2><p>Each slot can randomly use one or more selected rarities.</p><div class="field"><label>Structure name</label><input data-edit="structureName" value="${escapeHtml(p.structureName || '')}" placeholder="e.g. Standard 5-card pull" /></div><div class="structure-tools"><button class="small-button" data-action="export-structure">↑ Export structure</button><button class="small-button" data-action="import-structure">↓ Import structure</button></div><div class="row"><div class="field"><label>First rarity for new slot</label><select id="slot-rarity">${rarityOptions}</select></div><button class="button button-quiet inline-add" data-action="add-slot" ${p.rarities.length ? '' : 'disabled'}>Add slot</button></div><div class="slot-list">${p.slots.map((slot, i) => { const choices = Array.isArray(slot) ? slot : [slot]; return `<div class="slot"><span class="slot-index">${String(i + 1).padStart(2,'0')}</span><select multiple data-slot="${i}" title="Select every rarity allowed in this slot">${p.rarities.map(r => `<option value="${r.id}" ${choices.includes(r.id) ? 'selected' : ''}>${escapeHtml(r.name)}</option>`).join('')}</select><button data-action="remove-slot" data-index="${i}">Remove</button></div>`; }).join('')}</div><p class="helper">Hold Ctrl on Windows or Cmd on Mac to choose multiple rarities in a slot.</p></div></div></div><div class="panel cards-section"><h2>03 / Card list</h2><p>Add cards under their rarity. Card pools are used when a slot rolls that rarity.</p><div class="rarity-columns">${p.rarities.map(r => rarityEditor(p,r)).join('')}</div></div>`; }
function rarityEditor(p, rarity) { const cards = p.cards.filter(c => c.rarity === rarity.id); return `<div class="rarity-block"><div class="rarity-title"><h3>${escapeHtml(rarity.name)}</h3><span>${cards.length} card${cards.length === 1 ? '' : 's'}</span></div>${cards.map(c => `<div class="card-entry"><img class="thumb" src="${escapeHtml(c.image)}" alt="" onerror="this.style.display='none'" /><input data-card="${c.id}" data-key="name" value="${escapeHtml(c.name)}" placeholder="Card name" /><input data-card="${c.id}" data-key="image" value="${escapeHtml(c.image)}" placeholder="Image URL" /><button class="small-button delete" data-action="remove-card" data-id="${c.id}">×</button></div>`).join('')}<button class="small-button" data-action="add-card" data-rarity="${rarity.id}">+ Add card</button></div>`; }
function startOpening(id) { const p = data.packs.find(x => x.id === id); const byRarity = rarity => p.cards.filter(c => c.rarity === rarity); view.page = 'opening'; view.packId = id; view.revealIndex = -1; view.opening = p.slots.map(slot => { const choices = Array.isArray(slot) ? slot : [slot]; const selected = choices[Math.floor(Math.random() * choices.length)]; const rarity = p.rarities.find(r => r.id === selected) || p.rarities[0]; const pool = rarity ? byRarity(rarity.id) : []; const card = pool[Math.floor(Math.random() * pool.length)] || { id: uid(), name: 'Mystery card', image: '' }; return { ...card, rarityName: rarity?.name || 'Unknown' }; }); render(); }

function action(type, meta={}) { if (type === 'home') { view.page='home'; render(); return; } if (type === 'new-pack') { view.editor = { id:null, name:'', cover:'', description:'', structureName:'', rarities:[], slots:[], cards:[] }; view.page='editor'; render(); return; } if (type === 'random-open') { if (data.packs.length) startOpening(data.packs[Math.floor(Math.random() * data.packs.length)].id); else toast('Create a pack before opening one.'); return; } if (type === 'edit') { view.editor = structuredClone(data.packs.find(p=>p.id===meta.id)); view.page='editor'; render(); return; } if (type === 'open') { startOpening(meta.id); return; } if (type === 'info') { view.packId=meta.id; view.page='info'; render(); return; } if (type === 'favorite') { const p=data.packs.find(p=>p.id===meta.id); p.favorite=!p.favorite; save(); render(); return; } if (type === 'delete') { if (confirm('Delete this pack?')) { data.packs=data.packs.filter(p=>p.id!==meta.id); save(); render(); } return; } if (type === 'reveal') { view.revealIndex++; if (view.revealIndex >= 0 && view.revealIndex < view.opening.length) data.obtained[view.opening[view.revealIndex].id] = (data.obtained[view.opening[view.revealIndex].id] || 0) + 1; save(); render(); return; } if (type === 'add-rarity') { const input=document.getElementById('new-rarity'); if(input.value.trim()) { view.editor.rarities.push({id:uid(),name:input.value.trim()}); input.value=''; render(); } return; } if (type === 'remove-rarity') { view.editor.rarities=view.editor.rarities.filter(r=>r.id!==meta.id); view.editor.slots=view.editor.slots.map(slot => (Array.isArray(slot) ? slot : [slot]).filter(id=>id!==meta.id)).filter(slot=>slot.length); view.editor.cards=view.editor.cards.filter(c=>c.rarity!==meta.id); render(); return; } if (type === 'add-slot') { const select=document.getElementById('slot-rarity'); if(select?.value) view.editor.slots.push([select.value]); render(); return; } if (type === 'remove-slot') { view.editor.slots.splice(Number(meta.index),1); render(); return; } if (type === 'add-card') { view.editor.cards.push({id:uid(),name:'New card',image:'',rarity:meta.rarity}); render(); return; } if (type === 'remove-card') { view.editor.cards=view.editor.cards.filter(c=>c.id!==meta.id); render(); return; } if (type === 'export-structure') { structureExport(); return; } if (type === 'import-structure') { document.getElementById('structure-file').click(); return; } if (type === 'save-pack') { if(!view.editor.name.trim()) return toast('Give your pack a name first.'); if(!view.editor.rarities.length) return toast('Add at least one rarity.'); if(!view.editor.slots.length) return toast('Add at least one pack slot.'); const pack={...view.editor,id:view.editor.id||uid(),slots:view.editor.slots.map(slot=>Array.isArray(slot)?slot:[slot])}; const index=data.packs.findIndex(p=>p.id===pack.id); if(index>=0)data.packs[index]=pack;else data.packs.push(pack); save(); toast('Pack saved to your collection.'); view.page='home'; render(); return; } if (type === 'export') exportData(); if (type === 'import') document.getElementById('import-file').click(); }

function home() { const matching = data.packs.filter(p => p.name.toLowerCase().includes(view.query.toLowerCase()) && (view.rarity !== 'favorites' || p.favorite)); const packs = [...matching].sort((a,b) => view.sort === 'name' ? a.name.localeCompare(b.name) : view.sort === 'cards' ? b.cards.length - a.cards.length : Number(b.favorite) - Number(a.favorite)); const totalCards = data.packs.reduce((sum,p) => sum + p.cards.length, 0); const ownedCards = data.packs.reduce((sum,p) => sum + p.cards.filter(c => data.obtained[c.id]).length, 0); return `<section class="hero"><div><div class="eyebrow">Your personal collection</div><h1>Open something<br><em>extraordinary.</em></h1></div><p>Build your own card universe, one pack at a time. Every opening is saved to your collection automatically.</p></section><div class="dashboard-stats"><div><span>Packs</span><strong>${data.packs.length}</strong></div><div><span>Cards collected</span><strong>${ownedCards}<small> / ${totalCards}</small></strong></div><div><span>Completion</span><strong>${totalCards ? Math.round(ownedCards / totalCards * 100) : 0}%</strong></div><button class="button button-primary" data-action="random-open">✦ Random pack</button></div><div class="toolbar"><input class="search" data-model="query" value="${escapeHtml(view.query)}" placeholder="Search packs..." /><select class="select" data-model="rarity"><option value="all">All packs</option><option value="favorites" ${view.rarity === 'favorites' ? 'selected' : ''}>Favorites</option></select><select class="select" data-model="sort"><option value="featured" ${view.sort !== 'name' && view.sort !== 'cards' ? 'selected' : ''}>Featured</option><option value="name" ${view.sort === 'name' ? 'selected' : ''}>Name</option><option value="cards" ${view.sort === 'cards' ? 'selected' : ''}>Most cards</option></select></div><div class="pack-grid">${packs.length ? packs.map(packCard).join('') : `<div class="empty"><strong>No packs found</strong>Try a different search or create your first pack.</div>`}</div>`; }
function packCard(pack, i) { const owned = pack.cards.filter(c => data.obtained[c.id]).length; const percent = pack.cards.length ? Math.round(owned / pack.cards.length * 100) : 0; return `<article class="pack-card" style="animation-delay:${i * 60}ms"><div class="pack-cover" data-action="open" data-id="${pack.id}">${cover(pack)}</div><div class="pack-meta"><div><h3>${escapeHtml(pack.name)}</h3><p>${pack.cards.length} cards · ${pack.slots.length} per pack</p></div><button class="favorite ${pack.favorite ? 'active' : ''}" data-action="favorite" data-id="${pack.id}">${pack.favorite ? '★' : '☆'}</button></div><div class="pack-progress"><span>Collection ${percent}%</span><i><b style="width:${percent}%"></b></i></div><div class="card-actions"><button class="icon-button" title="View pack info" data-action="info" data-id="${pack.id}">◉</button><button class="icon-button" title="Edit pack" data-action="edit" data-id="${pack.id}">✎</button><button class="icon-button" title="Delete pack" data-action="delete" data-id="${pack.id}">×</button></div></article>`; }

function info() { const p = data.packs.find(x => x.id === view.packId); const obtained = data.obtained; const search = (view.collectionSearch || '').toLowerCase(); const owned = p.cards.filter(c => obtained[c.id]).length; return `<section class="editor-head collection-title"><div><div class="eyebrow">Pack archive</div><h1>${escapeHtml(p.name)}</h1><p class="helper">${owned} of ${p.cards.length} cards collected</p></div><div class="editor-actions"><button class="button button-quiet" data-action="home">← Back</button><button class="button button-primary" data-action="open" data-id="${p.id}">Open pack</button></div></section><div class="collection-toolbar"><input class="search" data-model="collectionSearch" value="${escapeHtml(view.collectionSearch || '')}" placeholder="Search cards in this pack..." /></div><div class="collection-browser">${p.rarities.map(r => { const cards = p.cards.filter(c => c.rarity === r.id && c.name.toLowerCase().includes(search)); if (!cards.length) return ''; return `<section class="rarity-row"><div class="rarity-row-head"><div><span class="eyebrow">Rarity</span><h2>${escapeHtml(r.name)}</h2></div><span>${cards.filter(c => obtained[c.id]).length} / ${cards.length} collected</span></div><div class="rarity-cards">${cards.map(c => `<figure class="collection-card ${obtained[c.id] ? '' : 'unowned'}">${c.image ? `<img src="${escapeHtml(c.image)}" alt="${escapeHtml(c.name)}" />` : '<div class="mini-fallback"><span>NO IMAGE</span></div>'}<figcaption><strong>${escapeHtml(c.name)}</strong><small>${obtained[c.id] ? 'Collected' : 'Unobtained'}</small></figcaption></figure>`).join('')}</div></section>`; }).join('') || `<div class="empty"><strong>No cards found</strong>Try a different card name.</div>`}</div>`; }

function bind() { document.querySelectorAll('[data-action]').forEach(el => el.addEventListener('click', () => action(el.dataset.action, el.dataset))); document.querySelectorAll('[data-model]').forEach(el => el.addEventListener('input', e => { view[e.target.dataset.model] = e.target.value; render(); })); document.querySelectorAll('[data-model="rarity"]').forEach(el => el.addEventListener('change', e => { view.rarity = e.target.value; render(); })); document.querySelectorAll('[data-edit]').forEach(el => el.addEventListener('input', e => { view.editor[e.target.dataset.edit] = e.target.value; })); document.querySelectorAll('[data-slot]').forEach(el => el.addEventListener('change', e => { view.editor.slots[Number(e.target.dataset.slot)] = Array.from(e.target.selectedOptions).map(option => option.value); })); document.querySelectorAll('[data-card]').forEach(el => el.addEventListener('input', e => { const card = view.editor.cards.find(c => c.id === e.target.dataset.card); if (card) card[e.target.dataset.key] = e.target.value; })); }
function structureExport() { const structure = { name: view.editor.structureName || 'Unnamed structure', rarities: view.editor.rarities, slots: view.editor.slots.map(slot => Array.isArray(slot) ? slot : [slot]) }; const blob = new Blob([JSON.stringify(structure, null, 2)], { type: 'application/json' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `${(structure.name || 'pack-structure').replace(/[^a-z0-9]+/gi, '-').toLowerCase()}.json`; a.click(); URL.revokeObjectURL(a.href); toast('Pack structure exported.'); }
function structureImport(file) { file.text().then(text => { const imported = JSON.parse(text); if (!Array.isArray(imported.rarities) || !Array.isArray(imported.slots)) throw Error(); view.editor.structureName = imported.name || ''; view.editor.rarities = imported.rarities.map(r => ({ id: r.id || uid(), name: String(r.name || 'Unnamed rarity') })); view.editor.slots = imported.slots.map(slot => Array.isArray(slot) ? slot : [slot]); view.editor.cards = view.editor.cards.filter(card => view.editor.rarities.some(r => r.id === card.rarity)); render(); toast('Pack structure imported.'); }).catch(() => toast('That file is not a valid pack structure.')); }
async function fetchWebPack() { const input = prompt('Paste a Fandom pack page URL:', 'https://digimoncardgame.fandom.com/wiki/BT-26:_BOOSTER_TIMELESS_BONDS'); if (!input) return; let pageUrl; try { pageUrl = new URL(input); } catch { return toast('Please enter a valid page URL.'); } if (!pageUrl.hostname.endsWith('fandom.com') || !pageUrl.pathname.startsWith('/wiki/')) return toast('Please use a Fandom wiki page URL.'); const page = decodeURIComponent(pageUrl.pathname.replace('/wiki/', '')); toast('Fetching pack data...'); try { const api = `${pageUrl.origin}/api.php?action=parse&page=${encodeURIComponent(page)}&prop=text&format=json&origin=*`; const response = await fetch(api); if (!response.ok) throw Error(); const payload = await response.json(); const html = payload?.parse?.text?.['*']; if (!html) throw Error(); const parsed = parsePackHtml(html, page); if (!parsed.cards.length) throw Error(); view.editor = parsed; view.page = 'editor'; render(); toast(`Fetched ${parsed.cards.length} cards. Review before saving.`); } catch { toast('Fandom blocked the request or no card table was detected. Try exporting page data and importing it.'); } }
function parsePackHtml(html, page) { const doc = new DOMParser().parseFromString(html, 'text/html'); const rarityNames = new Map(); const cards = []; const rarityPattern = /secret rare|special rare|super rare|ultra rare|rare|uncommon|common|promo|parallel|alternate art/i; doc.querySelectorAll('table tr').forEach(row => { const cells = [...row.querySelectorAll('th,td')]; if (cells.length < 2) return; const text = cells.map(cell => cell.textContent.trim()).filter(Boolean); const rarityText = text.find(value => rarityPattern.test(value)); const image = row.querySelector('img'); const links = [...row.querySelectorAll('a[href*="/wiki/"]')]; const name = text.find(value => value.length > 2 && !rarityPattern.test(value) && !/^BT[- ]?\d+/i.test(value)) || links.map(link => link.textContent.trim()).find(Boolean); if (!name) return; const rarityName = (rarityText?.match(rarityPattern)?.[0] || 'Imported').replace(/\b\w/g, letter => letter.toUpperCase()); const rarityId = rarityName.toLowerCase().replace(/[^a-z0-9]+/g, '-'); rarityNames.set(rarityId, { id: rarityId, name: rarityName }); cards.push({ id: uid(), name: name.replace(/\s+/g, ' '), image: image?.src || image?.getAttribute('data-src') || '', rarity: rarityId }); }); const rarities = [...rarityNames.values()]; const title = page.replace(/_/g, ' ').replace(/\s+/g, ' ').trim(); return { id:null, name:title, cover:'', description:`Imported from ${title}`, structureName:'Imported structure', rarities, slots:rarities.map(r => [r.id]), cards, favorite:false }; }
document.getElementById('structure-file').addEventListener('change', e => { const file=e.target.files[0]; if(file) structureImport(file); e.target.value=''; });

function normalizeImageUrl(value='') { if (!value || value.startsWith('data:')) return ''; return value.startsWith('//') ? `https:${value}` : value; }
function imageSource(image) { return normalizeImageUrl(image?.getAttribute('data-src') || image?.getAttribute('data-image-src') || image?.getAttribute('src') || ''); }
function parsePackHtml(html, page) { const doc = new DOMParser().parseFromString(html, 'text/html'); const rarityNames = new Map(); const cards = []; const rarityPattern = /secret rare|special rare|super rare|ultra rare|rare|uncommon|common|promo|parallel|alternate art/i; doc.querySelectorAll('table tr').forEach(row => { const cells = [...row.querySelectorAll('th,td')]; if (cells.length < 2) return; const text = cells.map(cell => cell.textContent.trim()).filter(Boolean); const rarityText = text.find(value => rarityPattern.test(value)); const image = row.querySelector('img'); const links = [...row.querySelectorAll('a[href*="/wiki/"]')]; const name = text.find(value => value.length > 2 && !rarityPattern.test(value) && !/^BT[- ]?\d+/i.test(value)) || links.map(link => link.textContent.trim()).find(Boolean); if (!name) return; const rarityName = (rarityText?.match(rarityPattern)?.[0] || 'Imported').replace(/\b\w/g, letter => letter.toUpperCase()); const rarityId = rarityName.toLowerCase().replace(/[^a-z0-9]+/g, '-'); rarityNames.set(rarityId, { id: rarityId, name: rarityName }); cards.push({ id: uid(), name: name.replace(/\s+/g, ' '), image: imageSource(image), rarity: rarityId }); }); const rarities = [...rarityNames.values()]; const title = page.replace(/_/g, ' ').replace(/\s+/g, ' ').trim(); const metaCover = normalizeImageUrl(doc.querySelector('meta[property="og:image"], meta[name="twitter:image"]')?.getAttribute('content') || ''); const packImage = [...doc.querySelectorAll('img')].map(imageSource).find(url => /booster|pack|bt[-_ -]?\d+/i.test(url)) || ''; return { id:null, name:title, cover:metaCover || packImage, description:`Imported from ${title}`, structureName:'Imported structure', rarities, slots:rarities.map(r => [r.id]), cards, favorite:false }; }

let exportInProgress = false;
exportData = function() { if (exportInProgress) return; exportInProgress = true; const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'cpos-collection.json'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => { URL.revokeObjectURL(a.href); exportInProgress = false; }, 800); toast('Collection exported.'); };

function rarityTier(pack, rarityId) { const index = Math.max(0, pack.rarities.findIndex(r => r.id === rarityId)); return Math.min(4, Math.floor(index / Math.max(1, pack.rarities.length - 1) * 4)); }
function enhancedOpening() { const p = data.packs.find(x => x.id === view.packId), opening = view.opening || [], current = opening?.[view.revealIndex]; const tier = current ? rarityTier(p, current.rarityId) : 0; return `<section class="opening"><div class="opening-shell"><div class="opening-head"><div class="eyebrow">Opening sequence · ${p.slots.length} cards</div><h1>${escapeHtml(p.name)}</h1><p>${view.revealIndex < 0 ? 'The pack is ready. Reveal each card one at a time.' : view.revealIndex >= opening.length ? 'Pack opened. Cards added to your collection.' : 'A new card has appeared.'}</p></div><div class="stage rarity-stage-${tier}">${current ? `<div class="opening-card reveal rarity-card-tier-${tier}">${current.image ? `<img src="${escapeHtml(current.image)}" alt="${escapeHtml(current.name)}" />` : fallback(current.name)}${current.isNew ? '<span class="new-badge">NEW</span>' : ''}<div class="card-name"><div class="card-rarity">${escapeHtml(current.rarityName)}</div>${escapeHtml(current.name)}</div></div>` : `<div class="opening-card">${cover(p)}</div>`}</div><div class="opening-controls"><button class="button button-quiet" data-action="home">← Back to packs</button>${view.revealIndex < opening.length ? `<button class="button button-primary" data-action="reveal">${view.revealIndex < 0 ? 'Begin opening' : 'Reveal next card'} →</button>` : `<button class="button button-primary" data-action="open" data-id="${p.id}">Open one more</button>`}</div><div class="progress">${view.revealIndex < 0 ? 'READY' : `${Math.min(view.revealIndex + 1, opening.length)} / ${opening.length} REVEALED`}</div></div></section>`; }
function enhancedStartOpening(id) { const p = data.packs.find(x => x.id === id); const byRarity = rarity => p.cards.filter(c => c.rarity === rarity); p.openedCount = (p.openedCount || 0) + 1; save(); view.page = 'opening'; view.packId = id; view.revealIndex = -1; view.opening = p.slots.map(slot => { const choices = Array.isArray(slot) ? slot : [slot]; const selected = choices[Math.floor(Math.random() * choices.length)]; const rarity = p.rarities.find(r => r.id === selected) || p.rarities[0]; const pool = rarity ? byRarity(rarity.id) : []; const card = pool[Math.floor(Math.random() * pool.length)] || { id: uid(), name: 'Mystery card', image: '' }; return { ...card, rarityId: rarity?.id, rarityName: rarity?.name || 'Unknown', isNew: !data.obtained[card.id] }; }); render(); }
function enhancedPackCard(pack, i) { const owned = pack.cards.filter(c => data.obtained[c.id]).length; const percent = pack.cards.length ? Math.round(owned / pack.cards.length * 100) : 0; return `<article class="pack-card" style="animation-delay:${i * 60}ms"><div class="pack-cover" data-action="open" data-id="${pack.id}">${cover(pack)}</div><div class="pack-meta"><div><h3>${escapeHtml(pack.name)}</h3><p>${pack.cards.length} cards · ${pack.slots.length} per pack</p></div><button class="favorite ${pack.favorite ? 'active' : ''}" data-action="favorite" data-id="${pack.id}">${pack.favorite ? '★' : '☆'}</button></div><div class="pack-progress"><span>Collection ${percent}% · ${pack.openedCount || 0} opened</span><i><b style="width:${percent}%"></b></i></div><div class="card-actions"><button class="icon-button" title="View pack info" data-action="info" data-id="${pack.id}">◉</button><button class="icon-button" title="Edit pack" data-action="edit" data-id="${pack.id}">✎</button><button class="icon-button reset-button" title="Reset pack progress" data-action="reset-progress" data-id="${pack.id}">↺</button><button class="icon-button" title="Delete pack" data-action="delete" data-id="${pack.id}">×</button></div></article>`; }
function enhancedInfo() { const p = data.packs.find(x => x.id === view.packId); const obtained = data.obtained; const search = (view.collectionSearch || '').toLowerCase(); const owned = p.cards.filter(c => obtained[c.id]).length; return `<section class="editor-head collection-title"><div><div class="eyebrow">Pack archive · ${p.openedCount || 0} packs opened</div><h1>${escapeHtml(p.name)}</h1><p class="helper">${owned} of ${p.cards.length} cards collected</p></div><div class="editor-actions"><button class="button button-quiet" data-action="home">← Back</button><button class="button button-danger" data-action="reset-progress" data-id="${p.id}">Reset progress</button><button class="button button-primary" data-action="open" data-id="${p.id}">Open pack</button></div></section><div class="collection-toolbar"><input class="search" data-model="collectionSearch" value="${escapeHtml(view.collectionSearch || '')}" placeholder="Search cards in this pack..." /></div><div class="collection-browser">${p.rarities.map(r => { const cards = p.cards.filter(c => c.rarity === r.id && c.name.toLowerCase().includes(search)); if (!cards.length) return ''; return `<section class="rarity-row"><div class="rarity-row-head"><div><span class="eyebrow">Rarity</span><h2>${escapeHtml(r.name)}</h2></div><span>${cards.filter(c => obtained[c.id]).length} / ${cards.length} collected</span></div><div class="rarity-cards">${cards.map(c => `<figure class="collection-card ${obtained[c.id] ? '' : 'unowned'}">${c.image ? `<img src="${escapeHtml(c.image)}" alt="${escapeHtml(c.name)}" />` : '<div class="mini-fallback"><span>NO IMAGE</span></div>'}<figcaption><strong>${escapeHtml(c.name)}</strong><small>${obtained[c.id] || 0} ${obtained[c.id] === 1 ? 'copy' : 'copies'}</small></figcaption></figure>`).join('')}</div></section>`; }).join('') || `<div class="empty"><strong>No cards found</strong>Try a different card name.</div>`}</div>`; }
const originalAction = action; action = function(type, meta={}) { if (type === 'reset-progress') { const p = data.packs.find(x => x.id === meta.id); if (p && confirm(`Reset progress for ${p.name}?`)) { p.cards.forEach(card => delete data.obtained[card.id]); p.openedCount = 0; save(); toast('Pack progress reset.'); render(); } return; } originalAction(type, meta); };
packCard = enhancedPackCard; info = enhancedInfo; opening = enhancedOpening; startOpening = enhancedStartOpening;

function reviewOpening() { const p = data.packs.find(x => x.id === view.packId), openingCards = view.opening || [], current = openingCards?.[view.revealIndex], complete = view.revealIndex >= openingCards.length; const tier = current ? rarityTier(p, current.rarityId) : 0; return `<section class="opening"><div class="opening-shell"><div class="opening-head"><div class="eyebrow">Opening sequence · ${p.slots.length} cards</div><h1>${escapeHtml(p.name)}</h1><p>${complete ? 'Pack review complete. Every card from this opening is shown below.' : view.revealIndex < 0 ? 'The pack is ready. Reveal each card one at a time.' : 'A new card has appeared.'}</p></div>${complete ? `<div class="review-panel"><div class="review-heading"><div><span class="eyebrow">Pack review</span><h2>${openingCards.length} cards opened</h2></div><span>${p.openedCount || 0} total pack${p.openedCount === 1 ? '' : 's'} opened</span></div><div class="review-cards">${openingCards.map(card => `<article class="review-card ${card.isNew ? 'review-new' : ''}">${card.image ? `<img src="${escapeHtml(card.image)}" alt="${escapeHtml(card.name)}" />` : fallback(card.name)}${card.isNew ? '<span class="new-badge">NEW</span>' : ''}<div><small>${escapeHtml(card.rarityName)}</small><strong>${escapeHtml(card.name)}</strong><em>${data.obtained[card.id] || 0} ${data.obtained[card.id] === 1 ? 'copy' : 'copies'} owned</em></div></article>`).join('')}</div></div>` : `<div class="stage rarity-stage-${tier}">${current ? `<div class="opening-card reveal rarity-card-tier-${tier}">${current.image ? `<img src="${escapeHtml(current.image)}" alt="${escapeHtml(current.name)}" />` : fallback(current.name)}${current.isNew ? '<span class="new-badge">NEW</span>' : ''}<div class="card-name"><div class="card-rarity">${escapeHtml(current.rarityName)}</div>${escapeHtml(current.name)}</div></div>` : `<div class="opening-card">${cover(p)}</div>`}</div>`}<div class="opening-controls"><button class="button button-quiet" data-action="home">← Back to packs</button>${complete ? `<button class="button button-primary" data-action="open" data-id="${p.id}">Open one more</button>` : `<button class="button button-primary" data-action="reveal">${view.revealIndex < 0 ? 'Begin opening' : 'Reveal next card'} →</button><button class="button button-quiet" data-action="skip-opening">Skip to review</button>`}</div><div class="progress">${view.revealIndex < 0 ? 'READY' : `${Math.min(view.revealIndex + 1, openingCards.length)} / ${openingCards.length} REVEALED`}</div></div></section>`; }
const previousAction = action; action = function(type, meta={}) { if (type === 'skip-opening') { for (let i = Math.max(0, view.revealIndex + 1); i < view.opening.length; i++) { const id = view.opening[i].id; data.obtained[id] = (data.obtained[id] || 0) + 1; } view.revealIndex = view.opening.length; save(); render(); return; } previousAction(type, meta); };
opening = reviewOpening;

const baseHome = home;
home = function() { const manual = `<div class="manual-backdrop" data-action="close-manual"><section class="manual" role="dialog" aria-modal="true" aria-label="Keyboard shortcuts"><button class="manual-close" data-action="close-manual">×</button><div class="eyebrow">CPOS quick manual</div><h2>Keyboard shortcuts</h2><p>Use these shortcuts to move around faster.</p><div class="shortcut-list"><span><kbd>N</kbd> New pack</span><span><kbd>R</kbd> Random pack</span><span><kbd>/</kbd> Focus search</span><span><kbd>I</kbd> Import collection</span><span><kbd>E</kbd> Export collection</span><span><kbd>?</kbd> Open this manual</span><span><kbd>Space</kbd> Reveal next card</span><span><kbd>S</kbd> Skip to review</span><span><kbd>Esc</kbd> Return to packs</span></div></section></div>`; return baseHome() + (view.manual ? manual : ''); };
const actionWithReview = action; action = function(type, meta={}) { if (type === 'manual') { view.manual = true; render(); return; } if (type === 'close-manual') { view.manual = false; render(); return; } actionWithReview(type, meta); };
document.addEventListener('keydown', e => { const tag = e.target.tagName?.toLowerCase(); const typing = tag === 'input' || tag === 'textarea' || tag === 'select' || e.target.isContentEditable; if (view.manual && e.key === 'Escape') { action('close-manual'); return; } if (typing) { if (e.key === '/' && tag === 'input') return; return; } if (e.key === '?' && view.page === 'home') { e.preventDefault(); action('manual'); return; } const key = e.key.toLowerCase(); if (key === 'n' && view.page === 'home') action('new-pack'); else if (key === 'r' && view.page === 'home') action('random-open'); else if (key === 'i' && view.page === 'home') action('import'); else if (key === 'e' && view.page === 'home') action('export'); else if (e.key === '/' && view.page === 'home') { e.preventDefault(); document.querySelector('[data-model="query"]')?.focus(); } else if ((e.key === ' ' || e.key === 'Enter') && view.page === 'opening' && view.revealIndex < (view.opening || []).length) { e.preventDefault(); action('reveal'); } else if (key === 's' && view.page === 'opening' && view.revealIndex < (view.opening || []).length) action('skip-opening'); else if (e.key === 'Escape' && view.page !== 'home') action('home'); });
render();

bind = function() { document.querySelectorAll('[data-action]').forEach(el => el.addEventListener('click', () => action(el.dataset.action, el.dataset))); document.querySelectorAll('[data-model]').forEach(el => el.addEventListener('input', e => { const key = e.target.dataset.model; const value = e.target.value; const start = e.target.selectionStart; const end = e.target.selectionEnd; view[key] = value; render(); const next = document.querySelector(`[data-model="${key}"]`); if (next) { next.focus(); if (typeof next.setSelectionRange === 'function') next.setSelectionRange(start, end); } })); document.querySelectorAll('[data-model]').forEach(el => el.addEventListener('change', e => { view[e.target.dataset.model] = e.target.value; render(); })); document.querySelectorAll('[data-edit]').forEach(el => el.addEventListener('input', e => { view.editor[e.target.dataset.edit] = e.target.value; })); document.querySelectorAll('[data-slot]').forEach(el => el.addEventListener('change', e => { view.editor.slots[Number(e.target.dataset.slot)] = Array.from(e.target.selectedOptions).map(option => option.value); })); document.querySelectorAll('[data-card]').forEach(el => el.addEventListener('input', e => { const card = view.editor.cards.find(c => c.id === e.target.dataset.card); if (card) card[e.target.dataset.key] = e.target.value; })); };
document.addEventListener('contextmenu', e => { if (view.page === 'opening' && e.target.closest('.opening') && !e.target.closest('.opening-card, .opening-controls, button')) { e.preventDefault(); if (view.revealIndex < (view.opening || []).length) action('reveal'); } });
render();

const normalOpeningRenderer = opening;
opening = function() { let html = normalOpeningRenderer(); if (view.packRipping) { html = html.replace('The pack is ready. Reveal each card one at a time.', 'The seal is breaking...').replace('class="opening-card"', 'class="opening-card pack-ripping"'); } else if (view.revealIndex < 0) { html = html.replace('class="opening-card"', 'class="opening-card pack-waiting"'); } return html; };
const normalActionRenderer = action;
action = function(type, meta={}) { if (type === 'reveal' && view.page === 'opening' && view.revealIndex < 0 && !view.packRipping) { view.packRipping = true; render(); view.ripTimer = setTimeout(() => { view.packRipping = false; view.revealIndex = 0; const card = view.opening[0]; data.obtained[card.id] = (data.obtained[card.id] || 0) + 1; save(); render(); }, 700); return; } if (type === 'skip-opening' && view.packRipping) { clearTimeout(view.ripTimer); view.packRipping = false; } normalActionRenderer(type, meta); };
render();

// Keep the split-pack renderer last so legacy render overrides cannot replace it.
opening = function() { return splitPackOpening(); };
render();

// Final action layer: legacy declarations above must not replace speedrun or export controls.
const finalSpeedrunAction = action;
action = function(type, meta={}) { if (type === 'speedrun-menu') { view.speedrunMenu=true; render(); return; } if (type === 'close-speedrun-menu') { view.speedrunMenu=false; render(); return; } if (type === 'leaderboard-menu') { view.leaderboardMenu=true; render(); return; } if (type === 'close-leaderboard-menu') { view.leaderboardMenu=false; render(); return; } if (type === 'speedrun-start') { beginSpeedrun(document.getElementById('speedrun-pack')?.value); return; } if (type === 'speedrun-random') { if (data.packs.length) beginSpeedrun(data.packs[Math.floor(Math.random()*data.packs.length)].id); return; } if (type === 'speedrun-restart') { beginSpeedrun(meta.id || view.packId); return; } if (type === 'exit-speedrun') { view.speedrun=null; view.speedrunMenu=false; view.page='home'; view.revealIndex=-1; render(); return; } if (type === 'skip-opening' && view.speedrun) return; if (type === 'reveal' && view.speedrun) { speedrunReveal(); return; } if (type === 'export') { view.exportMenu=true; render(); return; } if (type === 'close-export-menu') { view.exportMenu=false; render(); return; } if (type === 'export-content') { view.exportMenu=false; exportPackContent(); render(); return; } if (type === 'export-user') { view.exportMenu=false; userDataExport(); render(); return; } finalSpeedrunAction(type, meta); };
const finalSpeedrunHome = home;
home = function() { return finalSpeedrunHome() + (view.speedrunMenu ? speedrunModal() : '') + (view.exportMenu ? exportModal() : '') + (view.leaderboardMenu ? leaderboardModal() : ''); };
const finalCardAction = action;
action = function(type, meta={}) { if (type === 'add-card') { view.editor.cards.push({id:uid(),name:'',image:'',rarity:meta.rarity}); render(); return; } finalCardAction(type, meta); };
setTimeout(() => { opening = function() { return splitPackOpening(); }; render(); }, 30);
